 export type LatLng = { lat: number; lng: number };
+
+const EARTH_RADIUS_KM = 6371.0088;
+
+function isFiniteNumber(value: unknown): value is number {
+  return typeof value === "number" && Number.isFinite(value);
+}
+
+function assertValidPoint(point: LatLng): void {
+  if (!isFiniteNumber(point.lat) || point.lat < -90 || point.lat > 90) {
+    throw new RangeError("latitude must be a finite number in -90..90");
+  }
+
+  if (!isFiniteNumber(point.lng) || point.lng < -180 || point.lng > 180) {
+    throw new RangeError("longitude must be a finite number in -180..180");
+  }
+}
+
+function toRadians(degrees: number): number {
+  return (degrees * Math.PI) / 180;
+}

 /** Great-circle distance in kilometres. */
 export function haversineKm(a: LatLng, b: LatLng): number {
-  throw new Error("not implemented");
+  assertValidPoint(a);
+  assertValidPoint(b);
+
+  const aLatRad = toRadians(a.lat);
+  const bLatRad = toRadians(b.lat);
+  const deltaLatRad = toRadians(b.lat - a.lat);
+  const deltaLngRad = toRadians(b.lng - a.lng);
+
+  const sinLat = Math.sin(deltaLatRad / 2);
+  const sinLng = Math.sin(deltaLngRad / 2);
+
+  const haversine = sinLat * sinLat + Math.cos(aLatRad) * Math.cos(bLatRad) * sinLng * sinLng;
+  const centralAngle = 2 * Math.atan2(Math.sqrt(haversine), Math.sqrt(1 - haversine));
+
+  return EARTH_RADIUS_KM * centralAngle;
 }

